@push('scripts')<script>$(function(){var t=$('#tax-codes-table'),x=$.fn.dataTable.render.text(),dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:t.data('url'),buttons:[window.erpExcelButton(t)],order:[[0,'asc']],columns:[{data:'code',name:'code',render:x.display},{data:'name',name:'name',render:x.display},{data:'kind_label',name:'kind',render:x.display},{data:'rate',name:'rate',className:'text-end',render:x.display},{data:'is_active',name:'is_active',render:function(v,type,row){return type==='display'?'<span class="badge '+(v&&!row.deleted_at?'text-bg-dark">ใช้งาน':'text-bg-secondary">ปิดใช้งาน')+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,type,row){var a=[];if(row.edit_url&& !row.deleted_at)a.push('<a class="btn btn-sm btn-outline-dark" href="'+x.display(row.edit_url)+'">แก้ไข</a>');if(row.delete_url)a.push('<button class="btn btn-sm btn-outline-danger js-delete-tax" data-url="'+x.display(row.delete_url)+'" type="button">ลบ</button>');return a.join(' ');}}]}));window.erpAjaxDelete({button:'.js-delete-tax',reload:'#tax-codes-table',confirm:'ยืนยันการลบ Tax Code นี้หรือไม่?'});});</script>@endpush
